DROP TABLE IF EXISTS `wms_borrow_record`;
CREATE TABLE `wms_borrow_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `item_instance_id` bigint NOT NULL COMMENT '器材实例ID',
  `borrow_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '借还状态',
  `borrower` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '借用人',
  `from_unit` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '发货单位',
  `to_unit` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '收货单位',
  `from_person` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '发货人',
  `to_person` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '收货人',
  `doc_date` date NULL DEFAULT NULL COMMENT '单据日期',
  `borrow_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '借用单号',
  `plan_return_date` date NULL DEFAULT NULL COMMENT '计划归还日期',
  `overdue_flag` tinyint NULL DEFAULT 0 COMMENT '是否逾期',
  `overdue_days` int NULL DEFAULT 0 COMMENT '逾期天数',
  `instance_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '器材编码',
  `borrow_time` datetime(3) NOT NULL COMMENT '借用时间',
  `return_time` datetime(3) NULL DEFAULT NULL COMMENT '归还时间',
  `borrow_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '借用备注',
  `return_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '归还备注',
  `original_warehouse_id` bigint NULL DEFAULT NULL COMMENT '借出前仓库',
  `original_area_id` bigint NULL DEFAULT NULL COMMENT '借出前库区',
  `original_rack_id` bigint NULL DEFAULT NULL COMMENT '借出前货架',
  `original_location_id` bigint NULL DEFAULT NULL COMMENT '借出前货位',
  `returned_warehouse_id` bigint NULL DEFAULT NULL COMMENT '归还后仓库',
  `returned_area_id` bigint NULL DEFAULT NULL COMMENT '归还后库区',
  `returned_rack_id` bigint NULL DEFAULT NULL COMMENT '归还后货架',
  `returned_location_id` bigint NULL DEFAULT NULL COMMENT '归还后货位',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(3) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime(3) NULL DEFAULT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_wms_borrow_record_no`(`borrow_no`) USING BTREE,
  INDEX `idx_wms_borrow_record_item_instance_id`(`item_instance_id`) USING BTREE,
  INDEX `idx_wms_borrow_record_status`(`borrow_status`) USING BTREE,
  INDEX `idx_wms_borrow_record_borrow_time`(`borrow_time`) USING BTREE,
  INDEX `idx_wms_borrow_record_item_status`(`item_instance_id`, `borrow_status`, `borrow_time`) USING BTREE,
  INDEX `idx_wms_borrow_record_overdue`(`overdue_flag`, `borrow_status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2057116912845168643 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '借还记录' ROW_FORMAT = DYNAMIC;

