DROP TABLE IF EXISTS `wms_item_instance`;
CREATE TABLE `wms_item_instance`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `instance_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '器材实例编码',
  `item_id` bigint NOT NULL COMMENT '器材ID',
  `sku_id` bigint NOT NULL COMMENT '规格ID',
  `instance_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '待入库' COMMENT '器材实例状态',
  `warehouse_id` bigint NULL DEFAULT NULL COMMENT '所属仓库',
  `area_id` bigint NULL DEFAULT NULL COMMENT '所属库区',
  `rack_id` bigint NULL DEFAULT NULL COMMENT '所属货架',
  `location_id` bigint NULL DEFAULT NULL COMMENT '所属货位',
  `source_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '来源类型',
  `source_order_id` bigint NULL DEFAULT NULL COMMENT '来源单据ID',
  `source_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '来源单据号',
  `receipt_order_detail_id` bigint NULL DEFAULT NULL COMMENT '来源入库单明细ID',
  `shipment_order_detail_id` bigint NULL DEFAULT NULL COMMENT '来源出库单明细ID',
  `source_order_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '来源单据类型',
  `box_id` bigint NULL DEFAULT NULL COMMENT '当前所在箱体ID',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(3) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime(3) NULL DEFAULT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_wms_item_instance_code`(`instance_code`) USING BTREE,
  INDEX `idx_wms_item_instance_item_id`(`item_id`) USING BTREE,
  INDEX `idx_wms_item_instance_sku_id`(`sku_id`) USING BTREE,
  INDEX `idx_wms_item_instance_source_order_id`(`source_order_id`) USING BTREE,
  INDEX `idx_wms_item_instance_receipt_detail_id`(`receipt_order_detail_id`) USING BTREE,
  INDEX `idx_wms_item_instance_location_id`(`location_id`) USING BTREE,
  INDEX `idx_wms_item_instance_item_sku`(`item_id`, `sku_id`) USING BTREE,
  INDEX `idx_wms_item_instance_location`(`warehouse_id`, `area_id`, `rack_id`, `location_id`) USING BTREE,
  INDEX `idx_wms_item_instance_box_id`(`box_id`) USING BTREE,
  INDEX `idx_wms_item_instance_source_order`(`source_order_type`, `source_order_id`) USING BTREE,
  INDEX `idx_wms_item_instance_shipment_detail`(`shipment_order_detail_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2056774828187533318 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '器材实例' ROW_FORMAT = DYNAMIC;

