-- ----------------------------
-- Table structure for wms_location
-- ----------------------------
DROP TABLE IF EXISTS `wms_location`;
CREATE TABLE `wms_location`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `location_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '货位编码',
  `location_name` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '货位名称',
  `warehouse_id` bigint NOT NULL COMMENT '所属仓库',
  `area_id` bigint NOT NULL COMMENT '所属库区',
  `rack_id` bigint NOT NULL COMMENT '所属货架',
  `location_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'enabled' COMMENT '货位状态',
  `row_no` int NULL DEFAULT NULL COMMENT '行号',
  `column_no` int NULL DEFAULT NULL COMMENT '列号',
  `length` decimal(18, 2) NULL DEFAULT NULL COMMENT '长',
  `width` decimal(18, 2) NULL DEFAULT NULL COMMENT '宽',
  `height` decimal(18, 2) NULL DEFAULT NULL COMMENT '高',
  `occupied_flag` tinyint NULL DEFAULT 0 COMMENT '是否占用',
  `sort_no` bigint NULL DEFAULT NULL COMMENT '排序',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(3) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime(3) NULL DEFAULT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_wms_location_pos_code`(`warehouse_id`, `area_id`, `rack_id`, `location_code`) USING BTREE,
  UNIQUE INDEX `uk_wms_location_grid`(`rack_id`, `row_no`, `column_no`) USING BTREE,
  INDEX `idx_wms_location_warehouse_id`(`warehouse_id`) USING BTREE,
  INDEX `idx_wms_location_area_id`(`area_id`) USING BTREE,
  INDEX `idx_wms_location_rack_id`(`rack_id`) USING BTREE,
  INDEX `idx_wms_location_status`(`location_status`) USING BTREE,
  INDEX `idx_wms_location_occupied`(`occupied_flag`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2056772972438700035 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '货位' ROW_FORMAT = DYNAMIC;

